### 1. sun.ts (new file: app/src/client/render/sun.ts)

```ts
import * as THREE from 'three';
import { vecAdd, vecScale, vecNormalize, type Vec3 } from '@shared/physics/vec';

/**
 * TASK-82: the system star rendered as a distant SUN — infinitely far,
 * fixed direction, like the skybox. The sim's star is at the origin and
 * every planet anchor lies along +X (planetAnchor = ((i+1)×10000, 0, 0)),
 * so from anywhere in the system the star is toward −X; the spawn gate
 * (100 u +X) faces −X, so a warped-in ship looks straight at the sun.
 * A small +Y keeps the sun above the y = 0 horizon.
 */

/** Unit direction from the system to the star (toward −X, slightly up). */
export const SUN_DIRECTION: Vec3 = vecNormalize({ x: -1, y: 0.12, z: 0 });

/**
 * Camera distance to the sun: inside the 420 u sky shell so the sun draws
 * OVER the skybox (TASK-75 keeps both camera-centred). The 2° angular
 * radius at this distance is the on-screen disc size.
 */
export const SUN_DISTANCE = 380;

/** The sun's angular radius in degrees (the on-screen disc). */
export const SUN_ANGULAR_RADIUS_DEG = 2;

/**
 * Pure: the sun's world position for a camera at `cameraPos` — always
 * SUN_DISTANCE along SUN_DIRECTION (so the sun is effectively infinitely
